import 'package:flatmates_app/core/domain/wire_enums.dart';
import 'package:flutter_test/flutter_test.dart';

import 'api_fixtures.dart';

/// `lib/core/domain/wire_enums.dart` is generated by `tool/gen_enums.py` from
/// the backend. These tests fail when the file is stale, and pin the rule for
/// a value this build does not know: null, never a real member.
void main() {
  final backend = apiFixtureGroup('enums');

  test('every generated enum has exactly the values the backend serves', () {
    expect(kWireEnumValues.keys.toSet(), backend.keys.toSet());
    for (final name in backend.keys) {
      expect(
        kWireEnumValues[name],
        (backend[name] as List).cast<String>(),
        reason: '$name is stale: run python3 tool/gen_enums.py',
      );
    }
  });

  test('platform is ios or android on the wire, never the Dart name', () {
    expect(DevicePlatform.ios.wire, 'ios');
    expect(DevicePlatform.android.wire, 'android');
    expect(DevicePlatform.ios.toJson(), 'ios');
    expect(DevicePlatform.ios.name, isNot('iOS'));
  });

  test('the sign-in method has the backend wire values', () {
    expect(AuthMethod.emailPassword.wire, 'email_password');
    expect(AuthMethod.phoneOtp.wire, 'phone_otp');
    expect(AuthMethod.fromJson('phone_password'), AuthMethod.phonePassword);
    // A method this build does not know is null, never another method.
    expect(AuthMethod.fromJson('passkey'), isNull);
  });

  test('every member round-trips through its wire value', () {
    for (final status in VisitStatus.values) {
      expect(VisitStatus.fromJson(status.toJson()), status);
    }
    for (final status in ListingModerationStatus.values) {
      expect(ListingModerationStatus.fromJson(status.wire), status);
    }
    expect(
      ListingModerationStatus.values.map((s) => s.wire),
      contains('paused'),
    );
  });

  test('a value this build does not know is null, not a real member', () {
    expect(VisitStatus.fromJson('ghosted'), isNull);
    expect(VisitStatus.fromJson('Confirmed'), isNull);
    expect(ListingModerationStatus.fromJson('approved'), isNull);
    expect(MessageType.fromJson(''), isNull);
    expect(FlatmatesProfileStatus.fromJson(3), isNull);
    expect(ConversationSource.fromJson(null), isNull);
  });
}
